UPDATE review SET
    review_star = #{reviewStar},
    review_image = #{reviewImage},
    review_title = #{reviewTitle},
    review_content = #{reviewContent},
    review_response = #{reviewResponse}
WHERE review_id = #{reviewId}
  AND users_id = #{usersId}

